package vn.edu.eaut.lab7.listener;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;@WebListener public class SessionListener implements HttpSessionListener{public void sessionCreated(HttpSessionEvent e){System.out.println("[Lab7] Session created: "+e.getSession().getId());}public void sessionDestroyed(HttpSessionEvent e){System.out.println("[Lab7] Session destroyed: "+e.getSession().getId());}}
